UPDATE quizzes SET title = 'Tribal Uprisings & Peasant Movements: Halba & Paralkot Revolts', title_hi = 'जनजातीय विद्रोह और किसान आंदोलन: हल्बा और परलकोट विद्रोह', description = 'This quiz strictly targets the Halba Revolt (1774) and Paralkot Rebellion (1825) for CGPSC Prelims preparation. It tests deep factual knowledge on dates, specific treaties, local symbols, and key historical figures involved in these early Bastar uprisings.', description_hi = 'यह क्विज सीजीपीएससी प्रारंभिक परीक्षा की तैयारी के लिए विशेष रूप से हल्बा विद्रोह (1774) और परलकोट विद्रोह (1825) पर केंद्रित है। यह इन प्रारंभिक बस्तर विद्रोहों में शामिल तिथियों, विशिष्ट संधियों, स्थानीय प्रतीकों और प्रमुख ऐतिहासिक शख्सियतों पर गहन तथ्यात्मक ज्ञान का परीक्षण करता है।' WHERE id = 1339;

UPDATE quizzes SET title = 'Tribal Uprisings: Tarapur & Meria Revolts', title_hi = 'जनजातीय विद्रोह: तारापुर और मेरिया विद्रोह', description = 'A highly targeted 30-question CGPSC quiz focusing exclusively on the Tarapur Revolt (1842-1854) and Meria Revolt (1842-1863). It tests intricate details regarding leaders, root causes, intervening officers, and specific historical outcomes under the Kakatiya rule.', description_hi = 'तारापुर विद्रोह (1842-1854) और मेरिया विद्रोह (1842-1863) पर विशेष रूप से केंद्रित 30 प्रश्नों का एक उच्च-स्तरीय सीजीपीएससी क्विज। यह काकतीय शासन के तहत नेताओं, मूल कारणों, हस्तक्षेप करने वाले अधिकारियों और विशिष्ट ऐतिहासिक परिणामों के संबंध में जटिल विवरणों का परीक्षण करता है।' WHERE id = 1340;

UPDATE quizzes SET title = 'Tribal Uprisings: Lingagiri, Koi & Muria Revolts', title_hi = 'जनजातीय विद्रोह: लिंगागिरी, कोई और मुड़िया विद्रोह', description = 'A definitive 30-question master quiz targeting the Lingagiri (1856), Koi (1859), and Muria (1876) tribal revolts under Kakatiya ruler Bhairam Dev. It tests deep factual knowledge of causes, British interventions, local leaders, and specific outcomes like the historic Muria Darbar.', description_hi = 'काकतीय शासक भैरमदेव के शासनकाल में हुए लिंगागिरी (1856), कोई (1859) और मुड़िया (1876) जनजातीय विद्रोहों पर लक्षित 30 प्रश्नों का एक मास्टर क्विज। यह कारणों, ब्रिटिश हस्तक्षेपों, स्थानीय नेताओं और ऐतिहासिक मुड़िया दरबार जैसे विशिष्ट परिणामों के गहन तथ्यात्मक ज्ञान का परीक्षण करता है।' WHERE id = 1341;
